parameters.content:
### 3. Limpiar cada fila
El Code recorre las filas y:
- encuentra cada columna aunque el encabezado diga `Correo `, `E-mail` o `correo`;
- escribe los nombres como nombres propios (`ANA FLORES` → `Ana Flores`);
- pasa los correos a minúsculas y revisa que tengan forma de correo;
- unifica ciudades (`SCZ`, `sta. cruz` → `Santa Cruz de la Sierra`);
- saltea las filas vacías.

Revisar la forma de un correo no dice si existe: para eso hay que escribirle.

parameters.jsCode:
// Cada ítem es una fila del CSV. Las claves salen del encabezado del archivo.
const normalizar = (t) => String(t ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();

// Una columna puede venir escrita de varias formas: buscamos la clave que se parezca.
const COLUMNAS = {
  nombre: ['nombre', 'nombres', 'nombre completo', 'name'],
  correo: ['correo', 'correo electronico', 'email', 'e-mail', 'mail'],
  equipo: ['equipo', 'team'],
  ciudad: ['ciudad', 'city', 'municipio'],
};
const leer = (fila, campo) => {
  for (const [clave, valor] of Object.entries(fila)) {
    if (COLUMNAS[campo].includes(normalizar(clave))) return String(valor ?? '');
  }
  return '';
};

// «  ana  FLORES » → «Ana Flores». «de», «del», «la» y «y» quedan en minúscula.
const MINUSCULAS = new Set(['de', 'del', 'la', 'las', 'los', 'y']);
const nombrePropio = (texto) =>
  texto.trim().replace(/\s+/g, ' ').toLowerCase().split(' ').filter(Boolean)
    .map((p, i) => (i > 0 && MINUSCULAS.has(p) ? p : p.charAt(0).toUpperCase() + p.slice(1)))
    .join(' ');

// La misma ciudad escrita de distintas formas (la clave va en minúsculas y sin tildes).
const CIUDADES = {
  'scz': 'Santa Cruz de la Sierra',
  'santa cruz': 'Santa Cruz de la Sierra',
  'sta. cruz': 'Santa Cruz de la Sierra',
  'sta cruz': 'Santa Cruz de la Sierra',
  'santa cruz de la sierra': 'Santa Cruz de la Sierra',
};

// Forma de correo: texto, una arroba, un dominio con punto y sin espacios. No confirma que el correo exista.
const FORMA_DE_CORREO = /^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i;

const filas = [];
for (const item of $input.all()) {
  const fila = item.json;
  const nombre = nombrePropio(leer(fila, 'nombre'));
  const correo = leer(fila, 'correo').trim().toLowerCase();
  const equipo = leer(fila, 'equipo').trim().replace(/\s+/g, ' ');
  const ciudadOriginal = leer(fila, 'ciudad').trim().replace(/\s+/g, ' ');
  const ciudad = CIUDADES[normalizar(ciudadOriginal)] ?? nombrePropio(ciudadOriginal);

  // Fila vacía (como «,,,»): no aporta nada, la salteamos.
  if (!nombre && !correo && !equipo && !ciudad) continue;

  const problemas = [];
  if (!nombre) problemas.push('falta el nombre');
  if (!correo) problemas.push('falta el correo');
  else if (!FORMA_DE_CORREO.test(correo)) problemas.push(`el correo «${correo}» no tiene forma de correo`);

  filas.push({ json: { nombre, correo, equipo, ciudad, valido: problemas.length === 0, problema: problemas.join('; ') } });
}
return filas;

